const company = $input.first().json;
const properties = company.properties || {};

// Get domain (fallback chain: domain → website → parse from url)
let domain = properties.domain || properties.website || '';

if (!domain) {
  throw new Error('No domain or website found for company');
}

// Clean the URL
let cleaned = domain.toLowerCase().trim();
cleaned = cleaned.replace(/^https?:\/\//, '');
cleaned = cleaned.replace(/^www\./, '');
cleaned = cleaned.replace(/\/.*$/, '');
cleaned = cleaned.replace(/\/$/, '');

const fullUrl = 'https://' + cleaned;

return [{
  json: {
    hubspot_id: company.id,
    company_name: properties.name || cleaned,
    website: fullUrl,
    domain: cleaned,
    existing_data: {
      industry: properties.industry,
      city: properties.city,
      state: properties.state,
      country: properties.country,
      employees: properties.numberofemployees,
      revenue: properties.annualrevenue,
      description: properties.description,
      founded: properties.founded_year
    }
  }
}];

// Get all input items
const items = $input.all();

// Get previous data from Clean Domain node
const previousData = $('Clean Domain').item.json;

// Try to get HTML from input
let html = '';
if (items && items.length > 0) {
  const input = items[0].json || {};
  html = input.data || input.body || '';
  if (typeof html !== 'string') {
    html = JSON.stringify(html);
  }
}

// If no HTML, return with empty text but continue
if (!html || html.length < 100) {
  return [{
    json: {
      ...previousData,
      website_text: `TITLE: ${previousData.company_name}\nMETA DESCRIPTION: Website could not be crawled\n\nCompany: ${previousData.company_name}\nDomain: ${previousData.domain}`,
      website_available: false,
      detected_tech: []
    }
  }];
}

// Remove noise
let cleaned = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ');

// Extract meta tags
const titleMatch = cleaned.match(/<title[^>]*>([^<]*)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : '';

const descMatch = cleaned.match(/<meta\s+name=["']description["']\s+content=["']([^"']*)["']/i);
const metaDescription = descMatch ? descMatch[1].trim() : '';

const ogDescMatch = cleaned.match(/<meta\s+property=["']og:description["']\s+content=["']([^"']*)["']/i);
const ogDescription = ogDescMatch ? ogDescMatch[1].trim() : '';

// Detect tech stack
const techIndicators = {
  'React': /react/i,
  'Next.js': /next\.js|nextjs|_next\//i,
  'Vue': /vue\.js|vuejs/i,
  'Angular': /angular/i,
  'Shopify': /shopify|cdn\.shopify/i,
  'WordPress': /wp-content|wp-includes/i,
  'HubSpot': /hs-scripts\.com|hubspot/i,
  'Segment': /segment\.com|analytics\.js/i,
  'Intercom': /intercom/i,
  'Stripe': /stripe\.com|stripe\.js/i,
  'Cloudflare': /cloudflare/i,
  'AWS': /amazonaws|aws-/i,
  'Google Analytics': /googletagmanager|google-analytics/i,
  'Mixpanel': /mixpanel/i,
  'Amplitude': /amplitude/i,
  'Vercel': /vercel/i
};

const detectedTech = [];
for (const [tech, pattern] of Object.entries(techIndicators)) {
  if (pattern.test(html)) {
    detectedTech.push(tech);
  }
}

// Remove HTML tags
cleaned = cleaned.replace(/<[^>]+>/g, ' ');

// Decode entities
cleaned = cleaned
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&apos;/g, "'");

// Collapse whitespace
cleaned = cleaned.replace(/\s+/g, ' ').trim();

// Limit to 5000 chars
const truncated = cleaned.substring(0, 5000);

const websiteText = `TITLE: ${title}
META DESCRIPTION: ${metaDescription}
OG DESCRIPTION: ${ogDescription}
DETECTED TECH STACK: ${detectedTech.join(', ') || 'Unknown'}

PAGE CONTENT:
${truncated}`;

return [{
  json: {
    ...previousData,
    website_text: websiteText,
    website_available: true,
    page_title: title,
    meta_description: metaDescription,
    detected_tech: detectedTech
  }
}];

