const items = $input.all();
const tavilyData = items && items.length > 0 ? items[0].json : {};

const cleanData = $('Extract Website Text').item.json;
const hubspotData = $('Fetch HubSpot Company').item.json.properties || {};

// Build comprehensive research context
const websiteText = cleanData.website_text || 'Website unavailable';
const detectedTech = (cleanData.detected_tech || []).join(', ') || 'Unknown';

// Format Tavily research
const tavilyAnswer = tavilyData.answer || '';
const tavilyResults = (tavilyData.results || []).slice(0, 5).map(r => 
  `Title: ${r.title}\nURL: ${r.url}\nContent: ${r.content?.substring(0, 800)}`
).join('\n\n---\n\n');

const prompt = `You are a Sales Ops expert scoring companies against an Ideal Customer Profile (ICP).

===== YOUR TARGET ICP =====
Industry: SaaS / B2B Software / Enterprise Software
Company Size: 50-500 employees
Funding Stage: Series A, B, or C
Tech Stack: Uses modern cloud tools (AWS, GCP, Azure, Kubernetes, React, Node, etc.)
Growth Signal: Hiring actively in past 90 days
Location: North America (US, Canada) or Europe (UK, Germany, France, Netherlands, etc.)

===== SCORING RUBRIC (100 points total) =====
- Industry Match (25 pts): 25 if pure SaaS/B2B software, 15 if tech-adjacent, 5 if hardware/services, 0 if unrelated
- Company Size (20 pts): 20 if 50-500 employees, 10 if 20-50 or 500-1000, 0 if <20 or >1000
- Funding Stage (15 pts): 15 if Series A/B/C, 10 if Seed or Series D, 5 if bootstrapped, 0 if acquired/public
- Tech Stack (15 pts): 15 if uses modern cloud/SaaS tools, 5 if basic web, 0 if outdated tech
- Growth Signals (15 pts): 15 if actively hiring + recent funding, 8 if some growth signals, 0 if declining
- Location (10 pts): 10 if US/EU, 5 if other developed markets, 0 if emerging markets

===== TIER CLASSIFICATION =====
- HOT (80-100): Perfect ICP fit, prioritize immediately
- WARM (60-79): Good fit, worth outreach
- COLD (40-59): Partial fit, low priority
- DISQUALIFIED (0-39): Not our ICP

===== COMPANY TO SCORE =====

Company Name: ${cleanData.company_name}
Domain: ${cleanData.domain}
Website: ${cleanData.website}

HubSpot Existing Data:
- Industry: ${hubspotData.industry || 'Unknown'}
- Employees: ${hubspotData.numberofemployees || 'Unknown'}
- Revenue: ${hubspotData.annualrevenue || 'Unknown'}
- Location: ${hubspotData.city || ''} ${hubspotData.state || ''} ${hubspotData.country || ''}
- Founded: ${hubspotData.founded_year || 'Unknown'}
- Description: ${hubspotData.description || 'Unknown'}

===== WEBSITE CONTENT =====
${websiteText.substring(0, 2500)}

===== DETECTED TECH STACK =====
${detectedTech}

===== TAVILY RESEARCH =====
${tavilyAnswer}

Additional Research:
${tavilyResults.substring(0, 3000)}

===== YOUR TASK =====
Score this company against the ICP. Return ONLY valid JSON (no markdown, no code fences):

{
  "icp_score": 0-100,
  "icp_tier": "HOT" | "WARM" | "COLD" | "DISQUALIFIED",
  "icp_reasoning": "2-3 sentence explanation of the score",
  "scoring_breakdown": {
    "industry_match": 0-25,
    "company_size": 0-20,
    "funding_stage": 0-15,
    "tech_stack": 0-15,
    "growth_signals": 0-15,
    "location": 0-10
  },
  "estimated_employees": number_or_null,
  "detected_industry": "string",
  "detected_funding_stage": "Seed" | "Series A" | "Series B" | "Series C" | "Series D+" | "Bootstrapped" | "Public" | "Unknown",
  "detected_tech_stack": ["tech1", "tech2"],
  "detected_signals": [
    {
      "type": "FUNDING" | "HIRING" | "GROWTH" | "PRODUCT" | "LEADERSHIP",
      "detail": "specific fact"
    }
  ],
  "red_flags": ["any concerns about fit"],
  "next_action": "one sentence recommendation for sales team"
}`;

return [{
  json: {
    ...cleanData,
    prompt: prompt,
    tavily_data: tavilyData
  }
}];

const items = $input.all();
const response = items && items.length > 0 ? items[0].json : {};

const cleanData = $('Extract Website Text').item.json;

// Try Gemini format first, then Groq
let text = response?.candidates?.[0]?.content?.parts?.[0]?.text 
        || response?.choices?.[0]?.message?.content 
        || '';

if (!text) {
  throw new Error('Both Gemini and Groq returned no text');
}

// Clean markdown fences
text = text.trim();
text = text.replace(/^```json\s*/i, '');
text = text.replace(/^```\s*/i, '');
text = text.replace(/```\s*$/i, '');
text = text.trim();

let scoring;
try {
  scoring = JSON.parse(text);
} catch (err) {
  throw new Error('Failed to parse ICP JSON: ' + err.message + '\n\nRaw: ' + text.substring(0, 500));
}

// Extract signals as formatted string for HubSpot
const signalsFormatted = (scoring.detected_signals || [])
  .map(s => `[${s.type}] ${s.detail}`)
  .join('\n');

// Extract tech stack as string
const techStackFormatted = (scoring.detected_tech_stack || cleanData.detected_tech || []).join(', ');

return [{
  json: {
    hubspot_id: cleanData.hubspot_id,
    company_name: cleanData.company_name,
    website: cleanData.website,
    domain: cleanData.domain,

    // Core ICP data
    icp_score: scoring.icp_score || 0,
    icp_tier: scoring.icp_tier || 'PENDING',
    icp_reasoning: scoring.icp_reasoning || 'No reasoning provided',

    // Detected properties
    estimated_employees: scoring.estimated_employees || null,
    detected_industry: scoring.detected_industry || 'Unknown',
    detected_funding_stage: scoring.detected_funding_stage || 'Unknown',
    detected_tech_stack: techStackFormatted,
    detected_signals: signalsFormatted,

    // Additional data
    scoring_breakdown: scoring.scoring_breakdown || {},
    red_flags: scoring.red_flags || [],
    next_action: scoring.next_action || '',

    // Full raw scoring
    scoring_json: scoring,

    // Metadata
    enrichment_date: new Date().toISOString(),
    enrichment_status: 'Enriched'
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  properties: {
    icp_score: Math.round(Number($json.icp_score) || 0),
    icp_tier: ['HOT', 'WARM', 'COLD', 'DISQUALIFIED', 'PENDING'].includes(String($json.icp_tier).toUpperCase()) ? String($json.icp_tier).toUpperCase() : 'PENDING',
    icp_reasoning: String($json.icp_reasoning || '').substring(0, 5000),
    enrichment_date: new Date(new Date().toISOString().split('T')[0]).getTime(),
    detected_signals: String($json.detected_signals || '').substring(0, 5000),
    tech_stack: String($json.detected_tech_stack || '').substring(0, 5000),
    estimated_employees: $json.estimated_employees ? Math.round(Number($json.estimated_employees)) : null
  }
}) }}

